import { $rootMap, $stageAssignedMap } from "../../DisplayObjectUtil";
/**
 * @description DisplayObjectContainer の子要素に設定した root と stage を解除
 *              Remove the root and stage set for the child elements of DisplayObjectContainer
 *
 * @param  {DisplayObjectContainer} display_object_container
 * @return {void}
 * @method
 * @protected
 */
export const execute = (display_object_container) => {
    const children = display_object_container.children;
    for (let idx = 0; idx < children.length; ++idx) {
        const child = children[idx];
        if (!child) {
            continue;
        }
        // set root and stage
        $rootMap.delete(child);
        $stageAssignedMap.delete(child.instanceId);
        if (child.isVideo) {
            child.pause();
        }
        if (!child.isContainerEnabled) {
            continue;
        }
        execute(child);
    }
};
